import java.util.Objects;

/**
 * Represents a pair of indices and their corresponding values in an array.
 */
class IndexPair {
    public final int leftIndex;
    public final int rightIndex;
    public final int leftValue;
    public final int rightValue;

    IndexPair(int leftIndex, int rightIndex, int leftValue, int rightValue) {
        this.leftIndex = leftIndex;
        this.rightIndex = rightIndex;
        this.leftValue = leftValue;
        this.rightValue = rightValue;
    }

    @Override
    public String toString() {
        return String.format("[%d, %d] = %d + %d", leftIndex, rightIndex, leftValue, rightValue);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof IndexPair)) return false;
        IndexPair pair = (IndexPair) o;
        return leftIndex == pair.leftIndex && rightIndex == pair.rightIndex;
    }

    @Override
    public int hashCode() {
        return Objects.hash(leftIndex, rightIndex);
    }
}

/**
 * Strategy interface for pair-finding algorithms in sorted arrays.
 */
interface PairFinder {
    IndexPair findPair(int[] sortedArray, int targetSum);
}

/**
 * Core two-pointers algorithm for traversing a sorted array with two indices.
 * Encapsulates the common pattern of moving two pointers based on comparisons.
 */
abstract class TwoPointersAlgorithm {
    protected static class Pointers {
        int left;
        int right;

        Pointers(int length) {
            this.left = 0;
            this.right = length - 1;
        }
    }

    protected final boolean isValidArray(int[] array) {
        return array != null && array.length >= 2;
    }

    protected abstract void processMatch(int[] array, Pointers pointers, int targetSum);
    protected abstract void processLessThan(Pointers pointers);
    protected abstract void processGreaterThan(Pointers pointers);
    protected abstract Object getResult();

    protected final Object execute(int[] array, int targetSum) {
        if (!isValidArray(array)) {
            return null;
        }

        Pointers pointers = new Pointers(array.length);

        while (pointers.left < pointers.right) {
            int currentSum = array[pointers.left] + array[pointers.right];

            if (currentSum == targetSum) {
                processMatch(array, pointers, targetSum);
            } else if (currentSum < targetSum) {
                processLessThan(pointers);
            } else {
                processGreaterThan(pointers);
            }
        }

        return getResult();
    }
}

/**
 * Two Pointers Algorithm implementation for finding pairs in sorted arrays.
 * Provides efficient algorithms for solving pair-finding problems with O(n) time complexity.
 */
class TwoPointersTechnique extends TwoPointersAlgorithm implements PairFinder {
    private static final TwoPointersTechnique INSTANCE = new TwoPointersTechnique();

    private IndexPair foundPair;

    public static TwoPointersTechnique getInstance() {
        return INSTANCE;
    }

    /**
     * Finds a pair of indices in a sorted array that sum to the target value.
     * Uses the two-pointers technique with convergent pointers.
     *
     * @param sortedArray a sorted integer array
     * @param targetSum   the target sum to find
     * @return IndexPair containing indices and values if found, null otherwise
     * Time: O(n), Space: O(1)
     */
    @Override
    public IndexPair findPair(int[] sortedArray, int targetSum) {
        foundPair = null;
        execute(sortedArray, targetSum);
        return foundPair;
    }

    /**
     * Checks if a pair exists in a sorted array that sums to the target value.
     *
     * @param sortedArray a sorted integer array
     * @param targetSum   the target sum to find
     * @return true if a pair exists, false otherwise
     * Time: O(n), Space: O(1)
     */
    public boolean pairExists(int[] sortedArray, int targetSum) {
        return findPair(sortedArray, targetSum) != null;
    }

    /**
     * Counts the number of pairs in a sorted array that sum to the target value.
     *
     * @param sortedArray a sorted integer array
     * @param targetSum   the target sum to find
     * @return the count of pairs that sum to targetSum
     * Time: O(n), Space: O(1)
     */
    public int countPairs(int[] sortedArray, int targetSum) {
        PairCounter counter = new PairCounter();
        return (Integer) counter.execute(sortedArray, targetSum);
    }

    @Override
    protected void processMatch(int[] array, Pointers pointers, int targetSum) {
        foundPair = new IndexPair(pointers.left, pointers.right, array[pointers.left], array[pointers.right]);
    }

    @Override
    protected void processLessThan(Pointers pointers) {
        pointers.left++;
    }

    @Override
    protected void processGreaterThan(Pointers pointers) {
        pointers.right--;
    }

    @Override
    protected Object getResult() {
        return foundPair;
    }

    /**
     * Specialized two-pointers variant for counting matching pairs.
     */
    private static class PairCounter extends TwoPointersAlgorithm {
        private int count;

        @Override
        protected void processMatch(int[] array, Pointers pointers, int targetSum) {
            count++;
            pointers.left++;
            pointers.right--;
        }

        @Override
        protected void processLessThan(Pointers pointers) {
            pointers.left++;
        }

        @Override
        protected void processGreaterThan(Pointers pointers) {
            pointers.right--;
        }

        @Override
        protected Object getResult() {
            return count;
        }
    }
}

/**
 * Demonstration of the Two Pointers Technique algorithms.
 */
class TwoPointersTechniqueDemo {
    private static final TestCase[] TEST_CASES = {
        new TestCase(new int[]{-3, -1, 0, 1, 2}, -2),
        new TestCase(new int[]{1, 2, 3, 4, 5}, 7),
        new TestCase(new int[]{-5, -2, 0, 1, 3}, 1)
    };

    public static void main(String[] args) {
        TwoPointersTechnique technique = TwoPointersTechnique.getInstance();
        runAllDemonstrations(technique);
    }

    private static void runAllDemonstrations(TwoPointersTechnique technique) {
        for (TestCase testCase : TEST_CASES) {
            runDemonstrations(technique, testCase.array, testCase.target);
        }
    }

    private static void runDemonstrations(TwoPointersTechnique technique, int[] array, int target) {
        System.out.println("\n=== Test Case: target = " + target + " ===");
        demonstratePairSearch(technique, array, target);
        demonstrateExistenceCheck(technique, array, target);
        demonstratePairCounting(technique, array, target);
    }

    private static void demonstratePairSearch(TwoPointersTechnique technique, int[] array, int target) {
        IndexPair pair = technique.findPair(array, target);
        if (pair != null) {
            System.out.println("Pair found: " + pair);
        } else {
            System.out.println("No pair found");
        }
    }

    private static void demonstrateExistenceCheck(TwoPointersTechnique technique, int[] array, int target) {
        boolean exists = technique.pairExists(array, target);
        System.out.println("Pair exists: " + exists);
    }

    private static void demonstratePairCounting(TwoPointersTechnique technique, int[] array, int target) {
        int count = technique.countPairs(array, target);
        System.out.println("Number of pairs: " + count);
    }

    private static class TestCase {
        final int[] array;
        final int target;

        TestCase(int[] array, int target) {
            this.array = array;
            this.target = target;
        }
    }
}

